        animateSVG() {
            const svgPath = this.$el.querySelector(".svg-path");
            const svgGroup = this.$el.querySelector(".svg-group");
            svgPath.style.transition = "opacity 3s ease, fill 3s ease";
            svgGroup.style.transition = "opacity 3s ease";
